class Solution:
    def findMaxForm(self, strs: list[str], m: int, n: int) -> int:
        counts = [(s.count("0"), s.count("1")) for s in strs]
        def dfs(i: int, z: int, o: int) -> int:
            if i == len(counts):
                return 0
            ans = dfs(i + 1, z, o)
            cz, co = counts[i]
            if z >= cz and o >= co:
                ans = max(ans, 1 + dfs(i + 1, z - cz, o - co))
            return ans
        return dfs(0, m, n)

