class Solution:
    def findMaxForm(self, strs: list[str], m: int, n: int) -> int:
        from functools import lru_cache
        counts = [(s.count("0"), s.count("1")) for s in strs]
        @lru_cache(None)
        def dp(i: int, z: int, o: int) -> int:
            if i == len(counts):
                return 0
            ans = dp(i + 1, z, o)
            cz, co = counts[i]
            if z >= cz and o >= co:
                ans = max(ans, 1 + dp(i + 1, z - cz, o - co))
            return ans
        return dp(0, m, n)

