class Solution:
    def findMaxForm(self, strs: list[str], m: int, n: int) -> int:
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for s in strs:
            z = s.count("0")
            o = len(s) - z
            for zeros in range(m, z - 1, -1):
                for ones in range(n, o - 1, -1):
                    dp[zeros][ones] = max(dp[zeros][ones], dp[zeros - z][ones - o] + 1)
        return dp[m][n]

